using System;
using System.IO;
class FaultTest {
 static void Verify(string dir){if(Engine.HashFile(Path.Combine(dir,"00000000.cfsi"))!=Engine.P.archiveHash||Engine.HashFile(Path.Combine(dir,"ReZERO-TPT.exe"))!=Engine.P.exeBefore)throw new Exception("Original archive/executable not restored");foreach(var a in Engine.P.external)if(Engine.HashFile(Path.Combine(dir,a.name))!=a.before)throw new Exception("Original movie not restored");if(Directory.Exists(Path.Combine(dir,".rezero-arabic-backup")))throw new Exception("Backup cleanup did not finish");}
 static int Main(string[] args){try{string dir=args[0];bool fired=false;try{Engine.Install(dir,s=>{if(!fired&&s=="التحقق من التثبيت…"){fired=true;throw new OperationCanceledException("Injected interruption after video write");}});throw new Exception("Interruption not injected");}catch(OperationCanceledException){if(!fired)throw;}Verify(dir);
 string movie=Path.Combine(dir,Engine.P.external[0].name);byte[] saved=File.ReadAllBytes(movie);bool rejected=false;try{using(var f=File.OpenWrite(movie))f.WriteByte((byte)(saved[0]^1));try{Engine.Install(dir,s=>{});}catch(Exception){rejected=true;}if(!rejected||Directory.Exists(Path.Combine(dir,".rezero-arabic-backup")))throw new Exception("Changed movie not rejected before mutation");}finally{File.WriteAllBytes(movie,saved);}Verify(dir);File.WriteAllText(Path.Combine(dir,"faulttest-ok.txt"),"Post-write interruption rolled back all files. Altered movie rejected before mutation.");Console.WriteLine("Rollback and incompatible-video tests passed.");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
